"use client";

/**
 * Browser-side QR codes and downloads for "Comparte tu página": the codes are
 * drawn here from the salon's address (no image request to the API), so the
 * page, the printables and the image for social media always match.
 */
import QRCode from "qrcode";
import { displayUrl } from "./share-page";

const QR_OPTIONS = { errorCorrectionLevel: "M" as const, margin: 1 };

/** The QR code as SVG markup (generated by the qrcode library, not user input). */
export function qrSvg(url: string): Promise<string> {
  return QRCode.toString(url, { ...QR_OPTIONS, type: "svg" });
}

function saveBlob(blob: Blob, filename: string) {
  const href = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = href;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(href), 1000);
}

/** A PNG large enough to print sharp (1024 px by default). */
export async function downloadQrPng(url: string, filename: string, width = 1024) {
  const dataUrl = await QRCode.toDataURL(url, { ...QR_OPTIONS, width });
  const blob = await (await fetch(dataUrl)).blob();
  saveBlob(blob, filename);
}

export async function downloadQrSvg(url: string, filename: string) {
  saveBlob(new Blob([await qrSvg(url)], { type: "image/svg+xml" }), filename);
}

/** Largest font size (px) at which `text` fits in `maxWidth`. */
function fitFont(ctx: CanvasRenderingContext2D, text: string, weight: string, start: number, min: number, maxWidth: number) {
  let size = start;
  for (; size > min; size -= 2) {
    ctx.font = `${weight} ${size}px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif`;
    if (ctx.measureText(text).width <= maxWidth) break;
  }
  return size;
}

/**
 * A 1080 × 1080 image for WhatsApp status, Instagram or a post: the salon's
 * name, "Reserva tu cita", the QR code and the address.
 */
export async function socialImage(opts: { name: string; url: string; headline?: string }): Promise<Blob> {
  const S = 1080;
  const canvas = document.createElement("canvas");
  canvas.width = S;
  canvas.height = S;
  const ctx = canvas.getContext("2d")!;

  const bg = ctx.createLinearGradient(0, 0, S, S);
  bg.addColorStop(0, "#2e1065");
  bg.addColorStop(1, "#7c3aed");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, S, S);

  ctx.fillStyle = "#ffffff";
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";

  const headline = opts.headline ?? "Reserva tu cita";
  fitFont(ctx, headline, "800", 88, 40, S - 160);
  ctx.fillText(headline, S / 2, 165);

  ctx.fillStyle = "#ddd6fe";
  fitFont(ctx, opts.name, "600", 54, 28, S - 160);
  ctx.fillText(opts.name, S / 2, 245);

  // White card with the code.
  const card = 560;
  const x = (S - card) / 2;
  const y = 300;
  ctx.fillStyle = "#ffffff";
  ctx.beginPath();
  ctx.roundRect(x, y, card, card, 36);
  ctx.fill();
  const qr = document.createElement("canvas");
  await QRCode.toCanvas(qr, opts.url, { ...QR_OPTIONS, width: card - 60 });
  ctx.drawImage(qr, x + 30, y + 30, card - 60, card - 60);

  ctx.fillStyle = "#ffffff";
  const shown = displayUrl(opts.url);
  fitFont(ctx, shown, "700", 44, 24, S - 120);
  ctx.fillText(shown, S / 2, 940);

  ctx.fillStyle = "#ddd6fe";
  fitFont(ctx, "Escanea con la cámara del móvil · Reserva 24 h", "500", 32, 20, S - 120);
  ctx.fillText("Escanea con la cámara del móvil · Reserva 24 h", S / 2, 1000);

  return new Promise((resolve, reject) =>
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("No se pudo crear la imagen"))), "image/png"),
  );
}

export { saveBlob };
